    dy = enemy.y - me.y
    dist = hypot(dx, dy)
    r_me = hypot(me.x, me.y)
    if r_me > arena.radius - 1.0:
        target = bearing_to(0.0, 0.0)
    else:
        enemy_spinner_active = False
        if "front" in enemy.weapons:
            w = enemy.weapons["front"]
            if w.get("type") == "spinner" and w.get("health", 0.0) > 0.0 and abs(w.get("rpm", 0.0)) > 100.0:
                enemy_spinner_active = True
        if enemy_spinner_active and dist > 1.5:
            eh = radians(enemy.heading)
            ex = me.x - enemy.x
            ey = me.y - enemy.y
            ang = atan2(ey, ex) - eh
            while ang > pi:
                ang -= 2.0 * pi
            while ang < -pi:
                ang += 2.0 * pi
            if abs(ang) < radians(70.0):
                side = 1.0 if ang > 0.0 else -1.0
                ta = eh + side * pi / 2.0
                tx = enemy.x + 2.0 * cos(ta)
                ty = enemy.y + 2.0 * sin(ta)
                if hypot(tx, ty) > arena.radius - 0.5:
                    tx = enemy.x + 1.0 * cos(ta)
                    ty = enemy.y + 1.0 * sin(ta)
                target = bearing_to(tx, ty)
            else:
                target = bearing_to(enemy.x, enemy.y)
        else:
            target = bearing_to(enemy.x, enemy.y)
    steer = target / 45.0
    if steer > 1.0:
        steer = 1.0
    if steer < -1.0:
        steer = -1.0
    left = 1.0 - steer
    right = 1.0 + steer
    if left > 1.0:
        left = 1.0
    if left < -1.0:
        left = -1.0
    if right > 1.0:
        right = 1.0
    if right < -1.0:
        right = -1.0
