def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)
    dx = enemy.x - me.x
    dy = enemy.y - me.y
    dist = hypot(dx, dy)
    reach = 0.0
    if "front" in me.weapons:
        w = me.weapons["front"]
        if w.get("type") == "spinner" and w.get("axis") == "horizontal":
            reach = me.length / 2.0 + 2.0 * w.get("radius", 0.0)
    heading_rad = radians(me.heading)
    tip_x = me.x + reach * cos(heading_rad)
    tip_y = me.y + reach * sin(heading_rad)
    r_tip = hypot(tip_x, tip_y)
    back_x = me.x - (me.length / 2.0) * cos(heading_rad)
    back_y = me.y - (me.length / 2.0) * sin(heading_rad)
    r_back = hypot(back_x, back_y)
    side_x = me.x + (me.width / 2.0) * cos(heading_rad + pi / 2.0)
    side_y = me.y + (me.width / 2.0) * sin(heading_rad + pi / 2.0)
    r_side = hypot(side_x, side_y)
    max_r = max(r_tip, max(r_back, r_side))
    if max_r > arena.radius - 0.1:
        target = bearing_to(0.0, 0.0)
        steer = target / 45.0
        if steer > 1.0:
            steer = 1.0
        if steer < -1.0:
            steer = -1.0
        left = 1.0 - steer
        right = 1.0 + steer
        if left > 1.0:
            left = 1.0
        if left < -1.0:
            left = -1.0
        if right > 1.0:
            right = 1.0
        if right < -1.0:
            right = -1.0
        return (left, right)
    enemy_spinner_active = False
    if "front" in enemy.weapons:
        w = enemy.weapons["front"]
        if w.get("type") == "spinner" and w.get("health", 0.0) > 0.0:
            if abs(w.get("rpm", 0.0)) > 100.0:
                enemy_spinner_active = True
    eh = radians(enemy.heading)
    ex = me.x - enemy.x
    ey = me.y - enemy.y
    ang = atan2(ey, ex) - eh
    while ang > pi:
        ang -= 2.0 * pi
    while ang < -pi:
        ang += 2.0 * pi
    in_front = abs(ang) < radians(60.0)
    if enemy_spinner_active:
        desired_dist = 1.2
    else:
        desired_dist = 0.8
    if enemy_spinner_active and in_front and dist < 2.0:
        side = 1.0 if ang > 0.0 else -1.0
        ta = eh + side * pi / 2.0
        tx = enemy.x + 1.5 * cos(ta)
        ty = enemy.y + 1.5 * sin(ta)
        if hypot(tx, ty) > arena.radius - 1.0:
            tx = 0.0
            ty = 0.0
        target = bearing_to(tx, ty)
    else:
        if enemy_spinner_active:
            side = 1.0 if ang > 0.0 else -1.0
            perp_x = -sin(eh) * side * 0.4
            perp_y = cos(eh) * side * 0.4
            tx = enemy.x + perp_x
            ty = enemy.y + perp_y
            target = bearing_to(tx, ty)
        else:
            target = bearing_to(enemy.x, enemy.y)
    reverse = False
    if dist < desired_dist * 0.6:
        reverse = True
    steer = target / 45.0
    if steer > 1.0:
        steer = 1.0
    if steer < -1.0:
        steer = -1.0
    if reverse:
        left = -1.0 - steer
        right = -1.0 + steer
    else:
        left = 1.0 - steer
        right = 1.0 + steer
    if left > 1.0:
        left = 1.0
    if left < -1.0:
        left = -1.0
    if right > 1.0:
        right = 1.0
    if right < -1.0:
        right = -1.0
    return (left, right)

